import {drawHealingPools} from './healing-pools.js';
import {drawExtraEnemy,drawGemEffects} from './extra-render.js';
import {isBoss} from './monsters.js';
import {WORLD_SIZE} from './data.js';
import {clamp,seeded,distance} from './world.js';
const TAU=Math.PI*2;
function ellipse(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,TAU);c.fill()}
function poly(c,pts,color,stroke){c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.stroke()}}
function glow(c,x,y,r,color){const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2)}
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.w=0;this.h=0;this.camera={x:1200,y:1200};this.tile=null;this.seed=null;this.resize();new ResizeObserver(()=>this.resize()).observe(canvas)}
 resize(){const r=this.canvas.getBoundingClientRect();this.w=r.width;this.h=r.height;this.dpr=Math.min(window.devicePixelRatio||1,1.75);this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);this.zoom=this.w<650?.78:1}
 buildTerrain(world){this.seed=world.seed;const canvas=document.createElement('canvas');canvas.width=WORLD_SIZE;canvas.height=WORLD_SIZE;const c=canvas.getContext('2d'),rng=seeded(world.seed);c.fillStyle='#24372c';c.fillRect(0,0,WORLD_SIZE,WORLD_SIZE);
 // Static terrain is rasterized once per seed, not on every frame.
 for(let i=0;i<100;i++){const x=rng()*WORLD_SIZE,y=rng()*WORLD_SIZE,r=80+rng()*180;glow(c,x,y,r,i%3===0?'#75805728':'#14251e88')}
 c.lineCap='round';c.lineJoin='round';c.strokeStyle='#756b4730';c.lineWidth=78;c.beginPath();c.moveTo(0,1450);c.bezierCurveTo(550,1550,650,960,1200,1200);c.bezierCurveTo(1650,1400,1700,700,2400,920);c.stroke();c.strokeStyle='#8d835417';c.lineWidth=47;c.stroke();
 for(const d of world.decor){const {x,y,s}=d;if(d.type<.6){c.strokeStyle=d.type<.3?'#71815755':'#14251f99';c.lineWidth=1;c.beginPath();c.moveTo(x,y);c.lineTo(x-s*.3,y-s);c.moveTo(x,y);c.lineTo(x+s*.5,y-s*.7);c.stroke()}else if(d.type<.85){ellipse(c,x,y,s,s*.45,'#15291e77');ellipse(c,x,y-1,s*.7,s*.3,'#72795633')}else{c.fillStyle='#9e976c44';c.fillRect(x,y,2,2)}}
 // A navigable ruined circle marks the starting clearing.
 const x=1200,y=1200;c.strokeStyle='#89917635';c.lineWidth=2;c.beginPath();c.arc(x,y,141,0,TAU);c.stroke();c.beginPath();c.arc(x,y,111,0,TAU);c.stroke();for(let i=0;i<22;i++){const a=i*TAU/22;c.save();c.translate(x+Math.cos(a)*128,y+Math.sin(a)*128);c.rotate(a);c.fillStyle=i%3?'#747b5b36':'#a7a48144';c.fillRect(-10,-12,20,24);c.strokeStyle='#bec39a25';c.strokeRect(-8,-10,16,20);c.restore()}c.strokeStyle='#b6b48935';c.beginPath();c.moveTo(x-30,y);c.lineTo(x+30,y);c.moveTo(x,y-30);c.lineTo(x,y+30);c.stroke();
 c.strokeStyle='#acbd8155';c.lineWidth=8;c.strokeRect(9,9,WORLD_SIZE-18,WORLD_SIZE-18);this.tile=canvas;
 }
 draw(game,clock){if(this.seed!==game.seed)this.buildTerrain(game.world);const c=this.ctx,p=game.player,w=this.w,h=this.h,z=this.zoom;this.camera.x=clamp(p.x,w/z/2,WORLD_SIZE-w/z/2);this.camera.y=clamp(p.y,h/z/2,WORLD_SIZE-h/z/2);const cam=this.camera;c.setTransform(this.dpr,0,0,this.dpr,0,0);c.fillStyle='#16281e';c.fillRect(0,0,w,h);c.save();c.translate(w/2+(Math.random()-.5)*game.shake,h/2+(Math.random()-.5)*game.shake);c.scale(z,z);c.translate(-cam.x,-cam.y);const left=cam.x-w/z/2,top=cam.y-h/z/2;c.drawImage(this.tile,Math.max(0,left),Math.max(0,top),Math.min(WORLD_SIZE,w/z),Math.min(WORLD_SIZE,h/z),Math.max(0,left),Math.max(0,top),Math.min(WORLD_SIZE,w/z),Math.min(WORLD_SIZE,h/z));
 const visible=(o,r=100)=>Math.abs(o.x-cam.x)<w/z/2+r&&Math.abs(o.y-cam.y)<h/z/2+r;
 drawHealingPools(c,game,clock,visible);
 for(const g of game.gems){if(!visible(g,15))continue;const bob=Math.sin(clock*3+g.x)*2;glow(c,g.x,g.y,17,g.heal?'#e19b7555':'#bed78433');poly(c,[[g.x,g.y-6+bob],[g.x+4,g.y+bob],[g.x,g.y+6+bob],[g.x-4,g.y+bob]],g.heal?'#e9987f':g.value>7?'#c1dca0':'#b7c783','#dce6ad')}
 for(const zone of game.zones){c.strokeStyle=zone.color||(zone.active?'#ffa96b':'#e6866577');c.fillStyle=zone.color?zone.color+(zone.active?'55':'20'):(zone.active?'#e88a4d66':'#d8583820');c.lineWidth=2;c.beginPath();c.arc(zone.x,zone.y,zone.r,0,TAU);c.fill();c.stroke();if(!zone.active){c.beginPath();c.arc(zone.x,zone.y,zone.r*clamp(1-zone.timer/1.1,0,1),0,TAU);c.stroke()}}
 const drawables=[...game.world.obstacles.filter(o=>visible(o)),...game.enemies.filter(e=>visible(e)),{...p,type:'player',player:p}].sort((a,b)=>a.y-b.y);
 for(const o of drawables){if(o.type==='tree'||o.type==='rock')this.obstacle(c,o,distance(o,p)<o.r+65&&p.y<o.y);else if(o.type==='player')this.player(c,p,clock);else this.enemy(c,o,clock)}
 drawGemEffects(c,game);
 for(const s of game.shots){if(!visible(s,25))continue;const a=Math.atan2(s.vy,s.vx);glow(c,s.x,s.y,24,(s.color||'#ff962b')+'77');c.save();c.translate(s.x,s.y);c.rotate(a);poly(c,[[-20,0],[-5,-5],[4,-4],[8,0],[4,4],[-5,5]],s.color||'#ed782e');ellipse(c,0,0,7,4,s.id==='ice'?'#bcf0f4':'#ffc467');ellipse(c,3,0,4,2,'#fff2b2');c.restore()}
 for(const s of game.hostile){if(!visible(s,20))continue;glow(c,s.x,s.y,18,'#e0727c55');ellipse(c,s.x,s.y,s.r,s.r,s.color||'#d77f88');ellipse(c,s.x-1,s.y-1,s.r*.45,s.r*.45,'#ffd9c0')}
 for(let i=0;i<p.orbits;i++){const a=game.time*2.6+i*TAU/p.orbits,x=p.x+Math.cos(a)*66,y=p.y+Math.sin(a)*66;glow(c,x,y,25,'#ffaa4366');ellipse(c,x,y,9,9,'#f1ad53');ellipse(c,x,y,4,4,'#fff0ac')}
 for(const q of game.particles){if(!visible(q,10))continue;c.globalAlpha=clamp(q.life/q.max,0,1);c.fillStyle=q.color;c.fillRect(q.x,q.y,q.r,q.r)}c.globalAlpha=1;
 c.textAlign='center';c.font='bold 13px Arial';for(const t of game.texts){c.globalAlpha=clamp(t.life*2,0,1);c.fillStyle='#17241a';c.fillText(t.text,t.x+1,t.y+1);c.fillStyle=t.color;c.fillText(t.text,t.x,t.y)}c.globalAlpha=1;
 // Ember motes provide ambient motion without large particle allocations.
 for(let i=0;i<24;i++){const x=left+((i*113.7+clock*5)%(w/z)),y=top+((i*83.3-clock*7+h/z*10)%(h/z));c.globalAlpha=.2+Math.sin(clock+i)*.12;ellipse(c,x,y,1.4,1.4,'#e1cc8d')}c.globalAlpha=1;c.restore();
 const vignette=c.createRadialGradient(w/2,h/2,Math.min(w,h)*.15,w/2,h/2,Math.max(w,h)*.7);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#061811aa');c.fillStyle=vignette;c.fillRect(0,0,w,h);if(game.flash>0){c.fillStyle=`rgba(180,58,38,${game.flash*.65})`;c.fillRect(0,0,w,h)}
 if(game.boss&&game.boss.hp>0&&!visible(game.boss,0)){const a=Math.atan2(game.boss.y-p.y,game.boss.x-p.x),x=w/2+Math.cos(a)*(w/2-38),y=h/2+Math.sin(a)*(h/2-65);c.save();c.translate(x,y);c.rotate(a);poly(c,[[11,0],[-6,-7],[-6,7]],'#e6ac76');c.restore();c.fillStyle='#e6bd92';c.font='10px Arial';c.textAlign='center';c.fillText('BOSS',x,y+20)}
 this.minimap(c,game,w,h);
 }
 obstacle(c,o,fade){c.save();if(fade)c.globalAlpha=.45;const{x,y,r}=o;ellipse(c,x+8,y+6,r*1.35,r*.6,'#09180e66');if(o.type==='rock'){poly(c,[[x-r,y],[x-r*.8,y-r*.8],[x-r*.2,y-r*1.3],[x+r*.65,y-r],[x+r,y],[x+r*.4,y+r*.35],[x-r*.5,y+r*.25]],'#556052','#79816b');poly(c,[[x-r*.8,y-r*.8],[x-r*.2,y-r*1.3],[x+r*.65,y-r],[x+r*.2,y-r*.45],[x-r*.3,y-r*.4]],'#7d8570');poly(c,[[x-r*.3,y-r*.4],[x+r*.2,y-r*.45],[x+r*.4,y+r*.35],[x-r*.5,y+r*.25]],'#66715c');c.strokeStyle='#a0a38666';c.beginPath();c.moveTo(x-r*.2,y-r*.7);c.lineTo(x+r*.1,y-r*.25);c.lineTo(x-r*.1,y);c.stroke();ellipse(c,x-r*.5,y+3,r*.3,4,'#8d94604d')}
 else{c.fillStyle='#504c32';c.fillRect(x-5,y-r*.9,10,r*1.1);poly(c,[[x-5,y+3],[x-14,y+9],[x,y+6],[x+10,y+10],[x+5,y+2]],'#514b31');const layers=[{dy:0,s:1,col:'#1b392a',hi:'#38603b'},{dy:-r*.7,s:.8,col:'#254b30',hi:'#496e43'},{dy:-r*1.3,s:.57,col:'#375b38',hi:'#648352'}];for(const l of layers){const v=r*l.s,yy=y+l.dy;poly(c,[[x-v*1.25,yy-v*.25],[x-v*.75,yy-v*.62],[x-v*.92,yy-v*.72],[x,yy-v*1.6],[x+v*.84,yy-v*.76],[x+v*.64,yy-v*.62],[x+v*1.16,yy-v*.25],[x+v*.32,yy],[x,yy-v*.13],[x-v*.3,yy]],l.col);poly(c,[[x-v*.92,yy-v*.72],[x,yy-v*1.6],[x-v*.15,yy-v*.5],[x-v*.75,yy-v*.62]],l.hi)}}c.restore()}
 player(c,p,clock){const{x,y}=p,bob=Math.sin(p.walk)*1.4;c.save();if(p.invincible>0&&Math.floor(clock*20)%2===0)c.globalAlpha=.55;ellipse(c,x,y+10,18,7,'#06160da0');glow(c,x,y,60,'#d9bc5320');c.fillStyle='#372e24';c.fillRect(x-8,y+2+bob,5,10);c.fillRect(x+3,y+2-bob,5,10);poly(c,[[x-9,y-16],[x+7,y-16],[x+15,y+5],[x+9,y+9],[x-13,y+7]],'#b7b39a');poly(c,[[x-9,y-16],[x-3,y-12],[x-4,y+6],[x-13,y+7]],'#777e63');poly(c,[[x-10,y-13],[x-6,y-24],[x+3,y-28],[x+11,y-18],[x+9,y-9],[x+1,y-5]],'#cdbf99');poly(c,[[x-4,y-18],[x+6,y-18],[x+7,y-11],[x-3,y-11]],'#27322a');c.fillStyle='#f7d38b';c.fillRect(x+1,y-15,2,2);c.fillRect(x+5,y-15,2,2);c.strokeStyle='#8e754d';c.lineWidth=3;c.beginPath();c.moveTo(x+17,y+9);c.lineTo(x+19,y-29);c.stroke();glow(c,x+19,y-30,p.cast>0?55:25,'#f9b34666');poly(c,[[x+19,y-40],[x+24,y-31],[x+19,y-24],[x+14,y-31]],'#f9c16d');ellipse(c,x+19,y-31,2,4,'#fff4bf');if(p.dashTime>0){c.strokeStyle='#e7e1b577';c.lineWidth=2;c.beginPath();c.arc(x,y,23,0,TAU);c.stroke()}c.restore();c.strokeStyle='#d3c58855';c.lineWidth=1;c.beginPath();c.ellipse(x,y+11,21,9,0,0,TAU);c.stroke()}
 enemy(c,e,clock){const{x,y,r}=e,bob=Math.sin(clock*6+e.id)*2,hit=e.hit>0;c.save();ellipse(c,x,y+r*.45,r*1.1,r*.45,'#05180e77');if(e.attack>0){const a=e.aim;c.strokeStyle='#e5a072';c.fillStyle='#de804333';c.lineWidth=2;c.beginPath();if(isBoss(e)||e.type==='shaman')c.arc(x,y,r+10,0,TAU);else{c.moveTo(x,y);c.arc(x,y,r+27,a-.7,a+.7);c.closePath()}c.fill();c.stroke()}
 if(drawExtraEnemy(c,e,clock)){}else if(e.type==='crawler'){ellipse(c,x,y-4+bob,r,r*.77,hit?'#e8e5ca':'#697c4d');poly(c,[[x-r,y],[x-r*.8,y-15+bob],[x-r*.3,y-21+bob],[x,y-13+bob],[x+r*.4,y-20+bob],[x+r,y-6+bob]],hit?'#ffffdd':'#91a46b');c.fillStyle='#e8d499';c.fillRect(x-7,y-7+bob,4,3);c.fillRect(x+3,y-7+bob,4,3)}
 else if(e.type==='runner'){poly(c,[[x-12,y+4],[x-14,y-8+bob],[x-9,y-20+bob],[x-3,y-13+bob],[x+4,y-15+bob],[x+10,y-22+bob],[x+13,y-4+bob],[x+8,y+7]],hit?'#f8dfc2':'#ac7458');poly(c,[[x-7,y-9+bob],[x+7,y-9+bob],[x,y]],'#423f30');c.fillStyle='#f6bc7c';c.fillRect(x-6,y-9+bob,3,2);c.fillRect(x+3,y-9+bob,3,2)}
 else if(e.type==='shaman'){poly(c,[[x-16,y+8],[x-10,y-20+bob],[x,y-30+bob],[x+11,y-18+bob],[x+17,y+8]],hit?'#e3dcea':'#726882');poly(c,[[x-8,y-16+bob],[x+7,y-16+bob],[x+4,y-6+bob],[x-5,y-7+bob]],'#2b3331');c.fillStyle='#e4a7c0';c.fillRect(x-5,y-14+bob,3,3);c.fillRect(x+2,y-14+bob,3,3);glow(c,x+15,y-12,19,'#dd8dac44');ellipse(c,x+16,y-12,4,4,'#dba1b9')}
 else{const boss=e.type==='boss',s=boss?1.7:1,base=hit?'#e9d8b5':boss?'#8d7256':'#667163';c.save();c.translate(x,y);c.scale(s,s);poly(c,[[-22,8],[-24,-13],[-17,-27],[18,-27],[25,-10],[19,10]],base,'#a5947055');poly(c,[[-26,-16],[-32,-6],[-29,8],[-18,9],[-18,-13]],hit?'#ead9b5':'#586150');poly(c,[[22,-18],[31,-9],[29,8],[18,7],[17,-12]],hit?'#ead9b5':'#6b6850');poly(c,[[-15,-25],[-11,-39],[12,-39],[17,-26],[9,-16],[-9,-16]],hit?'#ffe5be':'#a0926b');poly(c,[[-13,-32],[-20,-46],[-9,-39]],'#a9a280');poly(c,[[11,-39],[23,-46],[17,-29]],'#a9a280');c.fillStyle=boss?'#ffc275':'#d9c68e';c.fillRect(-9,-30,6,3);c.fillRect(4,-30,6,3);poly(c,[[0,-13],[7,-4],[0,5],[-7,-4]],'#e1a05d');if(boss)glow(c,0,-4,20,'#e89d4277');c.restore()}
 if(e.hp<e.maxHp&&!isBoss(e)){c.fillStyle='#16271c';c.fillRect(x-r,y-r-20,r*2,3);c.fillStyle='#bcb582';c.fillRect(x-r,y-r-20,r*2*Math.max(0,e.hp/e.maxHp),3)}c.restore()}
 minimap(c,game,w,h){if(w<650)return;const size=88,x=w-size-20,y=h-size-45;c.fillStyle='#0d201aaa';c.fillRect(x,y,size,size);c.strokeStyle='#72805b66';c.strokeRect(x,y,size,size);const ratio=size/WORLD_SIZE;c.fillStyle='#6e825c88';for(const o of game.world.obstacles)c.fillRect(x+o.x*ratio,y+o.y*ratio,2,2);c.strokeStyle='#a6b48555';c.strokeRect(x+(this.camera.x-w/this.zoom/2)*ratio,y+(this.camera.y-h/this.zoom/2)*ratio,w/this.zoom*ratio,h/this.zoom*ratio);ellipse(c,x+game.player.x*ratio,y+game.player.y*ratio,2.5,2.5,'#f1d49b');if(game.boss&&game.boss.hp>0)ellipse(c,x+game.boss.x*ratio,y+game.boss.y*ratio,3,3,'#e68c66')}
}
